#define UA_SECURITYPOLICY_ECCBRAINPOOLP256R1_ASYM_SIGNING_KEY_LENGTH 32
#define UA_SECURITYPOLICY_ECCBRAINPOOLP256R1_ASYM_SIGNATURE_LENGTH 64
