    sp->certificateTypeId = UA_NS0ID(ECCBRAINPOOLP256R1APPLICATIONCERTIFICATETYPE);
    sp->securityLevel = 10;
    sp->policyType = UA_SECURITYPOLICYTYPE_ECC;

